import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.map.js";
import { GetAllApiDetails } from "@/mixins/GetAllApiDetails";
export default {
  props: {},
  mixins: [GetAllApiDetails],
  data: () => ({
    organisation: "",
    suborganisation: "",
    payloads: "",
    broadcast_api_key: "",
    api_details: "",
    ApiInvokeUrl: "",
    selectedCategoryId: "",
    selectedTicketTypeId: "",
    isLoading: true,
    ListAllApiDetails: []
  }),
  watch: {
    organisation() {
      this.suborganisation = "";
      this.updateDisplayedData();
    },
    suborganisation() {
      this.updateDisplayedData();
    }
  },
  computed: {
    OrganisationItems() {
      return this.ListAllApiDetails.map(c => ({
        title: c.category_name,
        value: c.category_id
      })) || [];
    },
    SuborganisationItems() {
      const selected = this.ListAllApiDetails.find(c => c.category_id === this.organisation);
      return selected?.ticket_types?.map(t => ({
        title: t.ticket_type_name,
        value: t.ticket_type_id
      })) || [];
    }
  },
  async mounted() {
    await this.GetAllApiDetailsMethod();
    if (this.ListAllApiDetails.length > 0) {
      this.organisation = this.ListAllApiDetails[0].category_id;
      const firstCategory = this.ListAllApiDetails[0];
      if (firstCategory.ticket_types && firstCategory.ticket_types.length > 0) {
        this.suborganisation = firstCategory.ticket_types[0].ticket_type_id;
      }
    }
    this.updateDisplayedData();
    this.isLoading = false;
  },
  methods: {
    updateDisplayedData() {
      const selectedCategory = this.ListAllApiDetails.find(c => c.category_id === this.organisation);
      if (!selectedCategory) {
        this.broadcast_api_key = "";
        this.payloads = "";
        this.selectedCategoryId = "";
        this.selectedTicketTypeId = "";
        return;
      }
      this.selectedCategoryId = selectedCategory.category_id;
      this.broadcast_api_key = selectedCategory.broadcast_api_key;
      this.api_details = this.ApiInvokeUrl;
      if (!this.suborganisation) {
        this.selectedTicketTypeId = "";
        this.payloads = JSON.stringify(selectedCategory.example_payloads?.using_category_id || {}, null, 2);
        return;
      }
      const selectedTicketType = selectedCategory.ticket_types.find(t => t.ticket_type_id === this.suborganisation);
      this.selectedTicketTypeId = selectedTicketType?.ticket_type_id || "";
      const payloadObj = selectedCategory.example_payloads?.using_ticket_type_id?.find(p => p.ticket_type_id === this.suborganisation);
      this.payloads = JSON.stringify(payloadObj || {}, null, 2);
    },
    resetDisplayedData() {
      this.broadcast_api_key = "";
      this.api_details = "";
      this.payloads = "";
    }
  }
};
